    value : std_logic_vector(3 downto 0);
    we    : std_logic;
  end record t_access_matrix_status_count_in;

  type t_access_matrix_status_fault_in is record
    value : std_logic;
    wel   : std_logic;
  end record t_access_matrix_status_fault_in;

  type t_access_matrix_status_from_hw is record
    busy  : std_logic;
    count : t_access_matrix_status_count_in;
    fault : t_access_matrix_status_fault_in;
  end record t_access_matrix_status_from_hw;

  type t_access_matrix_hw_modify_override_in is record
    value : std_logic_vector(3 downto 0);
    we    : std_logic;
  end record t_access_matrix_hw_modify_override_in;

  type t_access_matrix_hw_modify_sticky_in is record
    set : std_logic;
    clr : std_logic;
  end record t_access_matrix_hw_modify_sticky_in;

  type t_access_matrix_hw_modify_from_hw is record
    override : t_access_matrix_hw_modify_override_in;
    sticky   : t_access_matrix_hw_modify_sticky_in;
  end record t_access_matrix_hw_modify_from_hw;

  type t_access_matrix_hw_set_clear_set_only_in is record
    value : std_logic_vector(3 downto 0);
    set   : std_logic;
  end record t_access_matrix_hw_set_clear_set_only_in;

  type t_access_matrix_hw_set_clear_clr_only_in is record
    value : std_logic;
    clr   : std_logic;
  end record t_access_matrix_hw_set_clear_clr_only_in;

  type t_access_matrix_hw_set_clear_from_hw is record
    set_only : t_access_matrix_hw_set_clear_set_only_in;
    clr_only : t_access_matrix_hw_set_clear_clr_only_in;
  end record t_access_matrix_hw_set_clear_from_hw;

  type t_access_matrix_enum_hw_supply_in is record
    value : t_access_matrix_enum_hw_supply;
    we    : std_logic;
  end record t_access_matrix_enum_hw_supply_in;

  type t_access_matrix_enum_hw_from_hw is record
    state  : t_access_matrix_enum_hw_state;
    supply : t_access_matrix_enum_hw_supply_in;
  end record t_access_matrix_enum_hw_from_hw;

  type t_access_matrix_hw_status_swacc_latched_in is record
    value : std_logic_vector(3 downto 0);
    we    : std_logic;
  end record t_access_matrix_hw_status_swacc_latched_in;

  type t_access_matrix_hw_status_swacc_from_hw is record
    level   : std_logic_vector(3 downto 0);
    latched : t_access_matrix_hw_status_swacc_latched_in;
  end record t_access_matrix_hw_status_swacc_from_hw;

  type t_access_matrix_hw_only_from_hw is record
    shadow : std_logic_vector(3 downto 0);
  end record t_access_matrix_hw_only_from_hw;

  type t_access_matrix_irq_status_pending_in is record
    set : std_logic;
  end record t_access_matrix_irq_status_pending_in;

  type t_access_matrix_irq_status_from_hw is record
    pending : t_access_matrix_irq_status_pending_in;
  end record t_access_matrix_irq_status_from_hw;

  type t_access_matrix_flat_override_flat_override_in is record
    value : std_logic_vector(7 downto 0);
    we    : std_logic;
  end record t_access_matrix_flat_override_flat_override_in;

  type t_access_matrix_flat_flag_flat_flag_in is record
    set : std_logic;
    clr : std_logic;
  end record t_access_matrix_flat_flag_flat_flag_in;

  type t_access_matrix_from_hw is record
    status          : t_access_matrix_status_from_hw;
    hw_modify       : t_access_matrix_hw_modify_from_hw;
    hw_set_clear    : t_access_matrix_hw_set_clear_from_hw;
    enum_hw         : t_access_matrix_enum_hw_from_hw;
    hw_status_swacc : t_access_matrix_hw_status_swacc_from_hw;
    hw_only         : t_access_matrix_hw_only_from_hw;
    irq_status      : t_access_matrix_irq_status_from_hw;
    flat_override   : t_access_matrix_flat_override_flat_override_in;
    flat_status     : std_logic_vector(5 downto 0);
    flat_flag       : t_access_matrix_flat_flag_flat_flag_in;
  end record t_access_matrix_from_hw;

  constant C_ACCESS_MATRIX_FROM_HW_RESET : t_access_matrix_from_hw :=
  (
    status          =>
    (
      busy          => '0',
      count         => (value => (others => '0'), we => '0'),
      fault         => (value => '0', wel => '1')
    ),
    hw_modify       =>
    (
      override      => (value => (others => '0'), we => '0'),
      sticky        => (set => '0', clr => '0')
    ),
    hw_set_clear    =>
    (
      set_only      => (value => (others => '0'), set => '0'),
      clr_only      => (value => '0', clr => '0')
    ),
    enum_hw         =>
    (
      state         => ST_HALT,
      supply        => (value => PWR_OFF, we => '0')
    ),
    hw_status_swacc =>
    (
      level         => (others => '0'),
      latched       => (value => (others => '0'), we => '0')
    ),
    hw_only         => (shadow => (others => '0')),
    irq_status      =>
    (
      pending       => (set => '0')
    ),
    flat_override   =>
    (
      value         => (others => '0'),
      we            => '0'
    ),
    flat_status     => (others => '0'),
    flat_flag       =>
    (
      set           => '0',
      clr           => '0'
    )
  );

  -- True when check is false or the bits of addr from module_addr_width up equal base.
  function base_match (
    addr              : std_logic_vector(31 downto 0);
    base              : unsigned(31 downto 0);
    check             : boolean;
    module_addr_width : natural
  ) return boolean;

  -- True when addr is in the module's address range but above the registers.
  function above_registers (
    addr              : std_logic_vector(31 downto 0);
    module_addr_width : natural
  ) return boolean;

  -- True when reg_offset equals the register offset in reg_addr, every bit counting.
  function reg_addr_match (
    reg_offset : std_logic_vector(C_ACCESS_MATRIX_MODULE_ADDR_WIDTH - 1 downto 0);
    reg_addr   : std_logic_vector(31 downto 0)
  ) return boolean;

  -- True when a register sits at reg_offset.
  function is_mapped (
    reg_offset : std_logic_vector(C_ACCESS_MATRIX_MODULE_ADDR_WIDTH - 1 downto 0)
  ) return boolean;

  -- True when a register with a field software can write sits at reg_offset.
  function is_sw_writable (
    reg_offset : std_logic_vector(C_ACCESS_MATRIX_MODULE_ADDR_WIDTH - 1 downto 0)
  ) return boolean;

  -- True when a register with a field software can read sits at reg_offset.
  function is_sw_readable (
    reg_offset : std_logic_vector(C_ACCESS_MATRIX_MODULE_ADDR_WIDTH - 1 downto 0)
  ) return boolean;

end package access_matrix_regfile_pkg;

package body access_matrix_regfile_pkg is

  function base_match (
    addr              : std_logic_vector(31 downto 0);
    base              : unsigned(31 downto 0);
    check             : boolean;
    module_addr_width : natural
  ) return boolean is

    constant BASE_SLV : std_logic_vector(31 downto 0) := std_logic_vector(base);

  begin

    if not check then
      return true;
    end if;

    return addr(31 downto module_addr_width)
           = BASE_SLV(31 downto module_addr_width);

  end function base_match;

  function above_registers (
    addr              : std_logic_vector(31 downto 0);
    module_addr_width : natural
  ) return boolean is
  begin

    for i in C_ACCESS_MATRIX_MODULE_ADDR_WIDTH to module_addr_width - 1 loop

      if addr(i) /= '0' then
        return true;
      end if;

    end loop;

    return false;

  end function above_registers;

  function reg_addr_match (
    reg_offset : std_logic_vector(C_ACCESS_MATRIX_MODULE_ADDR_WIDTH - 1 downto 0);
    reg_addr   : std_logic_vector(31 downto 0)
  ) return boolean is
  begin

    return reg_offset = reg_addr(C_ACCESS_MATRIX_MODULE_ADDR_WIDTH - 1 downto 0);

  end function reg_addr_match;

  function is_mapped (
    reg_offset : std_logic_vector(C_ACCESS_MATRIX_MODULE_ADDR_WIDTH - 1 downto 0)
  ) return boolean is
  begin

    return reg_addr_match(reg_offset, C_ACCESS_MATRIX_PLAIN_OFFSET)
          or reg_addr_match(reg_offset, C_ACCESS_MATRIX_STATUS_OFFSET)
          or reg_addr_match(reg_offset, C_ACCESS_MATRIX_COMMAND_OFFSET)
          or reg_addr_match(reg_offset, C_ACCESS_MATRIX_IDENTITY_OFFSET)
          or reg_addr_match(reg_offset, C_ACCESS_MATRIX_HW_MODIFY_OFFSET)
          or reg_addr_match(reg_offset, C_ACCESS_MATRIX_HW_SET_CLEAR_OFFSET)
          or reg_addr_match(reg_offset, C_ACCESS_MATRIX_READ_EFFECTS_OFFSET)
          or reg_addr_match(reg_offset, C_ACCESS_MATRIX_WRITE_EFFECTS_OFFSET)
          or reg_addr_match(reg_offset, C_ACCESS_MATRIX_PULSES_OFFSET)
          or reg_addr_match(reg_offset, C_ACCESS_MATRIX_STROBES_OFFSET)
          or reg_addr_match(reg_offset, C_ACCESS_MATRIX_ENUM_VECTOR_OFFSET)
          or reg_addr_match(reg_offset, C_ACCESS_MATRIX_ENUM_BIT_OFFSET)
          or reg_addr_match(reg_offset, C_ACCESS_MATRIX_ENUM_HW_OFFSET)
          or reg_addr_match(reg_offset, C_ACCESS_MATRIX_ENUM_SWACC_OFFSET)
          or reg_addr_match(reg_offset, C_ACCESS_MATRIX_MIXED_SWACC_OFFSET)
          or reg_addr_match(reg_offset, C_ACCESS_MATRIX_MIXED_HISTORY_OFFSET)
          or reg_addr_match(reg_offset, C_ACCESS_MATRIX_HW_STATUS_SWACC_OFFSET)
          or reg_addr_match(reg_offset, C_ACCESS_MATRIX_HW_ONLY_OFFSET)
          or reg_addr_match(reg_offset, C_ACCESS_MATRIX_IRQ_STATUS_OFFSET)
          or reg_addr_match(reg_offset, C_ACCESS_MATRIX_FLAT_LEVEL_OFFSET)
          or reg_addr_match(reg_offset, C_ACCESS_MATRIX_FLAT_STROBE_OFFSET)
          or reg_addr_match(reg_offset, C_ACCESS_MATRIX_FLAT_OVERRIDE_OFFSET)
          or reg_addr_match(reg_offset, C_ACCESS_MATRIX_FLAT_STATUS_OFFSET)
          or reg_addr_match(reg_offset, C_ACCESS_MATRIX_FLAT_FLAG_OFFSET);

  end function is_mapped;

  function is_sw_writable (
    reg_offset : std_logic_vector(C_ACCESS_MATRIX_MODULE_ADDR_WIDTH - 1 downto 0)
  ) return boolean is
  begin

    return reg_addr_match(reg_offset, C_ACCESS_MATRIX_PLAIN_OFFSET)
          or reg_addr_match(reg_offset, C_ACCESS_MATRIX_COMMAND_OFFSET)
          or reg_addr_match(reg_offset, C_ACCESS_MATRIX_HW_MODIFY_OFFSET)
          or reg_addr_match(reg_offset, C_ACCESS_MATRIX_HW_SET_CLEAR_OFFSET)
          or reg_addr_match(reg_offset, C_ACCESS_MATRIX_READ_EFFECTS_OFFSET)
          or reg_addr_match(reg_offset, C_ACCESS_MATRIX_WRITE_EFFECTS_OFFSET)
          or reg_addr_match(reg_offset, C_ACCESS_MATRIX_PULSES_OFFSET)
          or reg_addr_match(reg_offset, C_ACCESS_MATRIX_STROBES_OFFSET)
          or reg_addr_match(reg_offset, C_ACCESS_MATRIX_ENUM_VECTOR_OFFSET)
          or reg_addr_match(reg_offset, C_ACCESS_MATRIX_ENUM_BIT_OFFSET)
          or reg_addr_match(reg_offset, C_ACCESS_MATRIX_ENUM_SWACC_OFFSET)
          or reg_addr_match(reg_offset, C_ACCESS_MATRIX_MIXED_SWACC_OFFSET)
          or reg_addr_match(reg_offset, C_ACCESS_MATRIX_MIXED_HISTORY_OFFSET)
          or reg_addr_match(reg_offset, C_ACCESS_MATRIX_HW_ONLY_OFFSET)
          or reg_addr_match(reg_offset, C_ACCESS_MATRIX_FLAT_LEVEL_OFFSET)
          or reg_addr_match(reg_offset, C_ACCESS_MATRIX_FLAT_STROBE_OFFSET)
          or reg_addr_match(reg_offset, C_ACCESS_MATRIX_FLAT_OVERRIDE_OFFSET)
          or reg_addr_match(reg_offset, C_ACCESS_MATRIX_FLAT_FLAG_OFFSET);

  end function is_sw_writable;

  function is_sw_readable (
    reg_offset : std_logic_vector(C_ACCESS_MATRIX_MODULE_ADDR_WIDTH - 1 downto 0)
  ) return boolean is
  begin

    return reg_addr_match(reg_offset, C_ACCESS_MATRIX_PLAIN_OFFSET)
          or reg_addr_match(reg_offset, C_ACCESS_MATRIX_STATUS_OFFSET)
          or reg_addr_match(reg_offset, C_ACCESS_MATRIX_IDENTITY_OFFSET)
          or reg_addr_match(reg_offset, C_ACCESS_MATRIX_HW_MODIFY_OFFSET)
          or reg_addr_match(reg_offset, C_ACCESS_MATRIX_HW_SET_CLEAR_OFFSET)
          or reg_addr_match(reg_offset, C_ACCESS_MATRIX_READ_EFFECTS_OFFSET)
          or reg_addr_match(reg_offset, C_ACCESS_MATRIX_WRITE_EFFECTS_OFFSET)
          or reg_addr_match(reg_offset, C_ACCESS_MATRIX_PULSES_OFFSET)
          or reg_addr_match(reg_offset, C_ACCESS_MATRIX_STROBES_OFFSET)
          or reg_addr_match(reg_offset, C_ACCESS_MATRIX_ENUM_VECTOR_OFFSET)
          or reg_addr_match(reg_offset, C_ACCESS_MATRIX_ENUM_BIT_OFFSET)
          or reg_addr_match(reg_offset, C_ACCESS_MATRIX_ENUM_HW_OFFSET)
          or reg_addr_match(reg_offset, C_ACCESS_MATRIX_ENUM_SWACC_OFFSET)
          or reg_addr_match(reg_offset, C_ACCESS_MATRIX_MIXED_SWACC_OFFSET)
          or reg_addr_match(reg_offset, C_ACCESS_MATRIX_MIXED_HISTORY_OFFSET)
          or reg_addr_match(reg_offset, C_ACCESS_MATRIX_HW_STATUS_SWACC_OFFSET)
          or reg_addr_match(reg_offset, C_ACCESS_MATRIX_HW_ONLY_OFFSET)
          or reg_addr_match(reg_offset, C_ACCESS_MATRIX_IRQ_STATUS_OFFSET)
          or reg_addr_match(reg_offset, C_ACCESS_MATRIX_FLAT_LEVEL_OFFSET)
          or reg_addr_match(reg_offset, C_ACCESS_MATRIX_FLAT_STROBE_OFFSET)
          or reg_addr_match(reg_offset, C_ACCESS_MATRIX_FLAT_OVERRIDE_OFFSET)
          or reg_addr_match(reg_offset, C_ACCESS_MATRIX_FLAT_STATUS_OFFSET)
          or reg_addr_match(reg_offset, C_ACCESS_MATRIX_FLAT_FLAG_OFFSET);

  end function is_sw_readable;

  function to_slv (
    v : t_access_matrix_identity_pwr_default
  ) return std_logic_vector is

    variable slv : std_logic_vector(0 downto 0);

  begin

    case v is

      when PWR_OFF =>

        slv := "0";

      when PWR_ON =>

        slv := "1";

    end case;

    return slv;

  end function to_slv;

  function to_access_matrix_identity_pwr_default (
    s : std_logic_vector(0 downto 0)
  ) return t_access_matrix_identity_pwr_default is
  begin

    case s is

      when "0" =>

        return PWR_OFF;

      when "1" =>

        return PWR_ON;

      when others =>

        return PWR_OFF;

    end case;

  end function to_access_matrix_identity_pwr_default;

  function to_slv (
    v : t_access_matrix_identity_pwr_spare
  ) return std_logic_vector is

    variable slv : std_logic_vector(0 downto 0);

  begin

    case v is

      when PWR_OFF =>

        slv := "0";

      when PWR_ON =>

        slv := "1";

    end case;

    return slv;

  end function to_slv;

  function to_access_matrix_identity_pwr_spare (
    s : std_logic_vector(0 downto 0)
  ) return t_access_matrix_identity_pwr_spare is
  begin

    case s is

      when "0" =>

        return PWR_OFF;

      when "1" =>

        return PWR_ON;

      when others =>

        return PWR_OFF;

    end case;

  end function to_access_matrix_identity_pwr_spare;

  function to_slv (
    v : t_access_matrix_enum_vector_mode
  ) return std_logic_vector is

    variable slv : std_logic_vector(1 downto 0);

  begin

    case v is

      when MODE_SLOW =>

        slv := "00";

      when MODE_FAST =>

        slv := "11";

    end case;

    return slv;

  end function to_slv;

  function to_access_matrix_enum_vector_mode (
    s : std_logic_vector(1 downto 0)
  ) return t_access_matrix_enum_vector_mode is
  begin

    case s is

      when "00" =>

        return MODE_SLOW;

      when "11" =>

        return MODE_FAST;

      when others =>

        return MODE_SLOW;

    end case;

  end function to_access_matrix_enum_vector_mode;

  function to_slv (
    v : t_access_matrix_enum_bit_power
  ) return std_logic_vector is

    variable slv : std_logic_vector(0 downto 0);

  begin

    case v is

      when PWR_OFF =>

        slv := "0";

      when PWR_ON =>

        slv := "1";

    end case;

    return slv;

  end function to_slv;

  function to_access_matrix_enum_bit_power (
    s : std_logic_vector(0 downto 0)
  ) return t_access_matrix_enum_bit_power is
  begin

    case s is

      when "0" =>

        return PWR_OFF;

      when "1" =>

        return PWR_ON;

      when others =>

        return PWR_OFF;

    end case;

  end function to_access_matrix_enum_bit_power;

  function to_slv (
    v : t_access_matrix_enum_hw_state
  ) return std_logic_vector is

    variable slv : std_logic_vector(1 downto 0);

  begin

    case v is

      when ST_RESET =>

        slv := "00";

      when ST_RUN =>

        slv := "01";

      when ST_HALT =>

        slv := "10";

    end case;

    return slv;

  end function to_slv;

  function to_access_matrix_enum_hw_state (
    s : std_logic_vector(1 downto 0)
  ) return t_access_matrix_enum_hw_state is
  begin

    case s is

      when "00" =>

        return ST_RESET;

      when "01" =>

        return ST_RUN;

      when "10" =>

        return ST_HALT;

      when others =>

        return ST_RESET;

    end case;

  end function to_access_matrix_enum_hw_state;

  function to_slv (
    v : t_access_matrix_enum_hw_supply
  ) return std_logic_vector is

    variable slv : std_logic_vector(0 downto 0);

  begin

    case v is

      when PWR_OFF =>

        slv := "0";

      when PWR_ON =>

        slv := "1";

    end case;

    return slv;

  end function to_slv;

  function to_access_matrix_enum_hw_supply (
    s : std_logic_vector(0 downto 0)
  ) return t_access_matrix_enum_hw_supply is
  begin

    case s is

      when "0" =>

        return PWR_OFF;

      when "1" =>

        return PWR_ON;

      when others =>

        return PWR_OFF;

    end case;

  end function to_access_matrix_enum_hw_supply;

  function to_slv (
    v : t_access_matrix_enum_swacc_phase
  ) return std_logic_vector is

    variable slv : std_logic_vector(1 downto 0);

  begin

    case v is

      when PH_IDLE =>

        slv := "00";

      when PH_ARM =>

        slv := "01";

      when PH_FIRE =>

        slv := "10";

    end case;

    return slv;

  end function to_slv;

  function to_access_matrix_enum_swacc_phase (
    s : std_logic_vector(1 downto 0)
  ) return t_access_matrix_enum_swacc_phase is
  begin

    case s is

      when "00" =>

        return PH_IDLE;

      when "01" =>

        return PH_ARM;

      when "10" =>

        return PH_FIRE;

      when others =>

        return PH_IDLE;

    end case;

  end function to_access_matrix_enum_swacc_phase;

  function to_slv (
    v : t_access_matrix_mixed_swacc_power
  ) return std_logic_vector is

    variable slv : std_logic_vector(0 downto 0);

  begin

    case v is

      when PWR_OFF =>

        slv := "0";

      when PWR_ON =>

        slv := "1";

    end case;

    return slv;

  end function to_slv;

  function to_access_matrix_mixed_swacc_power (
    s : std_logic_vector(0 downto 0)
  ) return t_access_matrix_mixed_swacc_power is
  begin

    case s is

      when "0" =>

        return PWR_OFF;

      when "1" =>

        return PWR_ON;

      when others =>

        return PWR_OFF;

    end case;

  end function to_access_matrix_mixed_swacc_power;

  function to_slv (
    v : t_access_matrix_mixed_swacc_power_fixed
  ) return std_logic_vector is

    variable slv : std_logic_vector(0 downto 0);

  begin

    case v is

      when PWR_OFF =>

        slv := "0";

      when PWR_ON =>

        slv := "1";

    end case;

    return slv;

  end function to_slv;

  function to_access_matrix_mixed_swacc_power_fixed (
    s : std_logic_vector(0 downto 0)
  ) return t_access_matrix_mixed_swacc_power_fixed is
  begin

    case s is

      when "0" =>

        return PWR_OFF;

      when "1" =>

        return PWR_ON;

      when others =>

        return PWR_OFF;

    end case;

  end function to_access_matrix_mixed_swacc_power_fixed;

end package body access_matrix_regfile_pkg;
